"""Generate src/display/lilly_gfx.h from font.py. Usage: python3 gen_header.py"""

import os

from font import ADV_X, ADV_Y, FONT, GLYPH_H, GLYPH_W, ICONS

HERE = os.path.dirname(os.path.abspath(__file__))
OUT = os.path.join(HERE, "..", "..", "src", "display", "lilly_gfx.h")


def rows_to_bits(rows):
    return [sum(1 << (len(r) - 1 - i) for i, ch in enumerate(r) if ch == "#") for r in rows]


lines = [
    "/* Generated by tools/oled/gen_header.py from tools/oled/font.py - do not edit. */",
    "#pragma once",
    "#include <stdint.h>",
    "",
    f"#define LILLY_GLYPH_W {GLYPH_W}",
    f"#define LILLY_GLYPH_H {GLYPH_H}",
    f"#define LILLY_ADV_X {ADV_X}",
    f"#define LILLY_ADV_Y {ADV_Y}",
    "",
    "/* ASCII 0x20..0x7E, 5 rows each, bit (W-1) = leftmost pixel; lowercase -> uppercase */",
    "static const uint8_t lilly_font[95][LILLY_GLYPH_H] = {",
]
for code in range(0x20, 0x7F):
    ch = chr(code)
    glyph = FONT.get(ch.upper()) or FONT["?"]
    bits = ", ".join(f"0x{b:x}" for b in rows_to_bits(glyph))
    esc = ch.replace("\\", "backslash")
    lines.append(f"    {{{bits}}}, /* {esc} */")
lines += ["};", ""]

for name, rows in ICONS.items():
    w, h = len(rows[0]), len(rows)
    bits = ", ".join(f"0x{b:x}" for b in rows_to_bits(rows))
    lines.append(f"#define LILLY_ICON_{name.upper()}_W {w}")
    lines.append(f"#define LILLY_ICON_{name.upper()}_H {h}")
    lines.append(f"static const uint8_t lilly_icon_{name}[{h}] = {{{bits}}};")
    lines.append("")

with open(OUT, "w") as f:
    f.write("\n".join(lines))
print("written", os.path.relpath(OUT))
